pause(): void {
  if (this.#state === 'closed') return;
  this.#state = 'paused';
}

resume(): void {
  if (this.#state === 'closed') return;
  this.#state = 'active';
  // Wake up iterator if waiting
  if (this.#eventResolver && this.#eventQueue.length > 0) {
    this.#eventResolver(this.#eventQueue.shift()!);
    this.#eventResolver = null;
  }
}
