// In constructor, after building blocks created:
if (options?.eventDelivery?.enabled !== false) {
  const subscriptionSequences = new Map<string, number>();

  this.eventBus.on('*', (event) => {
    const matchingSubs = this.subscriptions.match(event);

    for (const subId of matchingSubs) {
      const sub = this.subscriptions.get(subId);
      if (!sub || sub.paused) continue;

      if (options?.eventDelivery?.filter) {
        if (!options.eventDelivery.filter(event, sub)) continue;
      }

      const router = this.#findRouterForSession(sub.sessionId);
      if (!router) continue;

      const seq = (subscriptionSequences.get(subId) ?? 0) + 1;
      subscriptionSequences.set(subId, seq);

      router.notify(NOTIFICATION_METHODS.EVENT, {
        subscriptionId: subId,
        sequenceNumber: seq,
        eventId: event.id,
        timestamp: event.timestamp,
        event,
      }).catch((error) => {
        console.warn(`Event delivery failed for session ${sub.sessionId}:`, error.message);
        this.#removeConnection(sub.sessionId);
      });
    }
  });
}
