- [ ] Document that queued messages are lost

## Implementation Notes

```typescript
async close(options?: CloseOptions): Promise<void> {
  const { timeout = 5000, force = false } = options ?? {};

  // Force-expire disconnected sessions
  this.sessions.expireStale(0);

  if (force) {
    await Promise.all(
      [...this.#connections.values()].map(r => r.close())
    );
    this.#connections.clear();
    return;
  }

  // Graceful with timeout
  const closePromises = [...this.#connections.values()].map(async (router) => {
    try {
      await Promise.race([
        router.close(),
        new Promise((_, reject) => 
          setTimeout(() => reject(new Error('Timeout')), timeout)
        )
      ]);
    } catch {
      await router.close();
    }
  });

  await Promise.all(closePromises);
  this.#connections.clear();
}
```

